36	// mustQueryPointsFail 要求 query_points 查询失败并返回结构化错误。
37	func mustQueryPointsFail(t *testing.T, store *MetricStore, line string) *LineError {
38		t.Helper()
39		res, err := store.QueryPointsLine(line)
40		if err == nil {
41			t.Fatalf("expected query_points failure for %s, got result: %+v", line, res)
42		}
43		return err
44	}
