52	// queryPointsLabels 构造按标签子集查询的 query_points 对象文本。
53	func queryPointsLabels(name string, start, end int64, labels map[string]string) string {
54		return `{"op":"query_points","name":` + jsonString(name) +
55			fmt.Sprintf(`,"start":%d,"end":%d,"labels":`, start, end) + jsonLabels(labels) + `}`
