66	// TestQueryPointsSpecExample 是任务书示例：cpu、host=a 在 1000/2000/3000 上
67	// 分别存 2、4、9，查询 [1000,2000] 只列出前两个点，3000 上的点不出现。
68	func TestQueryPointsSpecExample(t *testing.T) {
69		store := NewMetricStore()
70		labels := map[string]string{"host": "a"}
71		mustOK(t, store, "["+
72			sample("cpu", 1000, 2, labels)+","+
73			sample("cpu", 2000, 4, labels)+","+
74			sample("cpu", 3000, 9, labels)+"]")
75	
76		res := mustQueryPoints(t, store, queryPointsLabels("cpu", 1000, 2000, labels))
77		if res.Status != "ok" || res.Op != "query_points" {
78			t.Fatalf("status/op = %q/%q, want ok/query_points", res.Status, res.Op)
79		}
80		if len(res.Series) != 1 {
81			t.Fatalf("series = %+v, want exactly one", res.Series)
82		}
83		s0 := res.Series[0]
84		if s0.Name != "cpu" || !sameLabels(s0.Labels, labels) {
85			t.Fatalf("series identity = %+v, want cpu{host=a}", s0)
86		}
87		assertPoints(t, s0, []Point{{Timestamp: 1000, Value: 2}, {Timestamp: 2000, Value: 4}},
88			"range [1000,2000] excludes the point at 3000")
89	
90		// start == end：只返回该时间戳上的采样。
91		res = mustQueryPoints(t, store, queryPointsLabels("cpu", 3000, 3000, labels))
92		assertPoints(t, res.Series[0], []Point{{Timestamp: 3000, Value: 9}}, "single timestamp 3000")
93		res = mustQueryPoints(t, store, queryPointsLabels("cpu", 1000, 1000, labels))
94		assertPoints(t, res.Series[0], []Point{{Timestamp: 1000, Value: 2}}, "single timestamp 1000")
95	
96		// 两个端点都包含：闭区间 [1000,3000] 列出全部三个点。
97		res = mustQueryPoints(t, store, queryPointsLabels("cpu", 1000, 3000, labels))
98		assertPoints(t, res.Series[0], []Point{
99			{Timestamp: 1000, Value: 2},
100			{Timestamp: 2000, Value: 4},
101			{Timestamp: 3000, Value: 9},
102		}, "inclusive range [1000,3000]")
103	}
