173	// TestQueryPointsLabelSelectionAndOrder 标签仍按子集规则匹配：省略或 {}
174	// 查该指标全部序列，返回记录保留完整标签集合而不缩减成查询条件；序列之间
175	// 沿用与 query 成功结果一致的排列次序，每条序列的点按时间戳升序；
176	// 无标签序列的 labels 为 {}。
177	func TestQueryPointsLabelSelectionAndOrder(t *testing.T) {
178		store := NewMetricStore()
179		// 故意乱序写入时间戳与序列，验证输出次序与输入顺序无关。
180		mustOK(t, store, `[
181			{"name":"m","timestamp":20,"value":2,"labels":{"zone":"x","host":"h"}},
182			{"name":"m","timestamp":10,"value":1},
183			{"name":"m","timestamp":30,"value":3,"labels":{"zone":"x"}},
184			{"name":"m","timestamp":10,"value":4,"labels":{"zone":"x","host":"h"}},
185			{"name":"m","timestamp":30,"value":5},
186			{"name":"m","timestamp":20,"value":6,"labels":{"zone":"x"}},
187			{"name":"other","timestamp":10,"value":9}
188		]`)
189	
190		// 省略 labels：该指标全部序列，次序与写入快照/query 一致
191		// （无标签在前，同指标名按排序后标签键值对字典序）。
192		res := mustQueryPoints(t, store, queryPointsAll("m", 0, 100))
193		if len(res.Series) != 3 {
194			t.Fatalf("all series = %+v, want 3", res.Series)
195		}
196		wantLabels := []map[string]string{
197			{},
198			{"host": "h", "zone": "x"},
199			{"zone": "x"},
200		}
201		wantPoints := [][]Point{
202			{{Timestamp: 10, Value: 1}, {Timestamp: 30, Value: 5}},
203			{{Timestamp: 10, Value: 4}, {Timestamp: 20, Value: 2}},
204			{{Timestamp: 20, Value: 6}, {Timestamp: 30, Value: 3}},
205		}
206		for i := range wantLabels {
207			s := res.Series[i]
208			if s.Name != "m" || !sameLabels(s.Labels, wantLabels[i]) {
209				t.Fatalf("series[%d] identity = %+v, want m%v", i, s, wantLabels[i])
210			}
211			assertPoints(t, s, wantPoints[i], fmt.Sprintf("series[%d] ascending points", i))
212		}
213		// 无标签序列的 labels 序列化为 {} 而不是 null。
214		if raw := marshalCompact(t, res.Series[0].Labels); raw != `{}` {
215			t.Fatalf("unlabeled series labels JSON = %s, want {}", raw)
216		}
217	
218		// 空对象等价于省略。
219		res = mustQueryPoints(t, store, `{"op":"query_points","name":"m","start":0,"end":100,"labels":{}}`)
220		if len(res.Series) != 3 {
221			t.Fatalf("empty labels = %+v, want all 3 series", res.Series)
222		}
223	
224		// 子集匹配 zone=x 命中两条序列，返回的完整标签集合不缩减成查询条件。
225		res = mustQueryPoints(t, store, queryPointsLabels("m", 0, 100, map[string]string{"zone": "x"}))
226		if len(res.Series) != 2 {
227			t.Fatalf("subset match = %+v, want 2 series", res.Series)
228		}
229		if !sameLabels(res.Series[0].Labels, map[string]string{"host": "h", "zone": "x"}) {
230			t.Fatalf("full labels must be preserved, got %v", res.Series[0].Labels)
231		}
232		if !sameLabels(res.Series[1].Labels, map[string]string{"zone": "x"}) {
233			t.Fatalf("full labels must be preserved, got %v", res.Series[1].Labels)
234		}
235	
236		// 区间过滤逐序列独立：只覆盖部分时间戳时，区间内没有点的序列不列出。
237		res = mustQueryPoints(t, store, queryPointsAll("m", 15, 25))
238		if len(res.Series) != 2 {
239			t.Fatalf("range [15,25] = %+v, want the two series with points inside", res.Series)
240		}
241		assertPoints(t, res.Series[0], []Point{{Timestamp: 20, Value: 2}}, "host=h series in [15,25]")
242		assertPoints(t, res.Series[1], []Point{{Timestamp: 20, Value: 6}}, "zone=x series in [15,25]")
243	
244		// name 精确匹配：不同指标不返回。
245		res = mustQueryPoints(t, store, queryPointsAll("other", 0, 100))
246		if len(res.Series) != 1 || res.Series[0].Name != "other" {
247			t.Fatalf("other metric = %+v", res.Series)
248		}
249	}
