1	package darksafe
2	
3	import (
4		"math/big"
5		"math/rand"
6		"testing"
7	)
8	
9	// 用 big.Int 参考实现核对窗口边界与窗口归属，覆盖接近 int64 上下界的区间。
10	func TestQueryWindowsReferenceDifferential(t *testing.T) {
11		cases := []struct {
12			start, end, step int64
13			ts               []int64
14		}{
15			{tsMinInt64, tsMaxInt64, tsMaxInt64, []int64{tsMinInt64, -2, -1, 0, 1, tsMaxInt64}},
16			{tsMinInt64, tsMaxInt64, 1, []int64{tsMinInt64, 0, tsMaxInt64}},
17			{-5, 4, 3, []int64{-5, -4, -1, 0, 1, 4}},
18			{1000, 3000, 1000, []int64{1000, 1999, 2000, 2999, 3000}},
19			{0, tsMaxInt64, tsMaxInt64, []int64{0, tsMaxInt64 - 1, tsMaxInt64}},
20			{tsMinInt64, tsMinInt64 + 10, 3, []int64{tsMinInt64, tsMinInt64 + 2, tsMinInt64 + 10}},
21			{tsMaxInt64 - 5, tsMaxInt64, 3, []int64{tsMaxInt64 - 5, tsMaxInt64 - 3, tsMaxInt64}},
22			{-10, 10, 7, []int64{-10, -4, -3, 3, 10}},
23		}
24		bStart := big.NewInt(0)
25		bEnd := big.NewInt(0)
26		bStep := big.NewInt(0)
27		bOne := big.NewInt(1)
28		for _, tc := range cases {
29			store := NewMetricStore()
30			line := "["
31			for i, ts := range tc.ts {
32				if i > 0 {
33					line += ","
34				}
35				line += sample("m", ts, float64(i+1), nil)
36			}
37			line += "]"
38			mustOK(t, store, line)
39			res := mustQueryWindows(t, store, queryWindowsAll("m", tc.start, tc.end, tc.step))
40	
41			// 参考分组：idx = (ts-start)/step（大整数整除），逐组累计点。
42			// idx 最大可达 2^64-1（step=1、跨整个 int64 区间），只能以 uint64 承载。
43			bStart.SetInt64(tc.start)
44			bEnd.SetInt64(tc.end)
45			bStep.SetInt64(tc.step)
46			groups := map[uint64][]int64{} // idx → timestamps
47			var order []uint64
48			for _, ts := range tc.ts {
49				if ts < tc.start || ts > tc.end {
50					continue
51				}
52				bTS := big.NewInt(ts)
53				idx := new(big.Int).Sub(bTS, bStart)
54				idx.Quo(idx, bStep)
55				if !idx.IsUint64() {
56					t.Fatalf("window idx overflows uint64: %v", idx)
57				}
58				k := idx.Uint64()
59				if _, ok := groups[k]; !ok {
60					order = append(order, k)
61				}
62				groups[k] = append(groups[k], ts)
63			}
64	
65			if len(res.Series) != 1 {
66				t.Fatalf("range [%d,%d] step %d: series = %+v", tc.start, tc.end, tc.step, res.Series)
67			}
68			got := res.Series[0].Windows
69			if len(got) != len(order) {
70				t.Fatalf("range [%d,%d] step %d: got %d windows %+v, want %d",
71					tc.start, tc.end, tc.step, len(got), got, len(order))
72			}
73			for i, k := range order {
74				// wStart = start + k*step；wEnd = min(wStart+step-1, end)。
75				ws := new(big.Int).Mul(new(big.Int).SetUint64(k), bStep)
76				ws.Add(ws, bStart)
77				we := new(big.Int).Add(ws, bStep)
78				we.Sub(we, bOne)
79				if we.Cmp(bEnd) > 0 {
80					we.Set(bEnd)
81				}
82				if !ws.IsInt64() || !we.IsInt64() {
83					t.Fatalf("window bounds overflow int64: [%v,%v]", ws, we)
84				}
85				if got[i].Start != ws.Int64() || got[i].End != we.Int64() {
86					t.Fatalf("window %d bounds = [%d,%d], want [%d,%d]",
87						k, got[i].Start, got[i].End, ws.Int64(), we.Int64())
88				}
89				if got[i].Count != len(groups[k]) {
90					t.Fatalf("window %d count = %d, want %d", k, got[i].Count, len(groups[k]))
91				}
92				// 检查窗口不倒置、不越界。
93				if got[i].Start > got[i].End || got[i].Start < tc.start || got[i].End > tc.end {
94					t.Fatalf("invalid window %+v within [%d,%d]", got[i], tc.start, tc.end)
95				}
96				// 平均 = (i+1) 的简单平均核对。
97				var sum float64
98				for _, ts := range groups[k] {
99					for j, x := range tc.ts {
100						if x == ts {
101							sum += float64(j + 1)
102						}
103					}
104				}
105				if got[i].Average != sum/float64(len(groups[k])) {
106					t.Fatalf("window %d average = %v, want %v", k, got[i].Average, sum/float64(len(groups[k])))
107				}
108			}
109		}
110	}
111	
112	// TestQueryWindowsRandomizedTiling 随机生成区间、步长与时间戳（含负数与接近
113	// int64 边界的值），直接核对输出窗口的归属、边界、截断与升序，不依赖参考分组。
114	func TestQueryWindowsRandomizedTiling(t *testing.T) {
115		rng := rand.New(rand.NewSource(20261006))
116		for iter := 0; iter < 300; iter++ {
117			var start, end, step int64
118			if rng.Intn(5) == 0 {
119				// 极端分支：起点贴近 int64 下界、小区间、步长取 int64 上界。
120				start = tsMinInt64 + int64(rng.Intn(5))
121				end = start + int64(rng.Intn(5))
122				step = tsMaxInt64
123			} else {
124				// 普通分支：起点限制在 2^60 内，保证 start+宽度 不会溢出 int64。
125				start = rng.Int63n(2 << 59)
126				if rng.Intn(2) == 0 {
127					start = -start
128				}
129				end = start + int64(rng.Intn(40)) // 小区间，宽度为 0..39
130				step = int64(1 + rng.Intn(50))
131			}
132			// 每个时间戳只写一次、值统一为 1（避免同位置冲突；计数按去重后的点）。
133			// ts 在 start-1..end+1 内抽取，顺带验证区间外的点既不入窗也不影响计数。
134			width := int(end-start) + 3
135			perm := rng.Perm(width)
136			n := 1 + rng.Intn(width)
137			inRange := map[int64]bool{}
138			line := "["
139			for i := 0; i < n; i++ {
140				ts := start - 1 + int64(perm[i])
141				if i > 0 {
142					line += ","
143				}
144				line += sample("m", ts, 1, nil)
145				if ts >= start && ts <= end {
146					inRange[ts] = true
147				}
148			}
149			line += "]"
150			store := NewMetricStore()
151			mustOK(t, store, line)
152			res := mustQueryWindows(t, store, queryWindowsAll("m", start, end, step))
153			if len(inRange) == 0 {
154				if len(res.Series) != 0 {
155					t.Fatalf("iter %d: expected empty series, got %+v", iter, res.Series)
156				}
157				continue
158			}
159			if len(res.Series) != 1 {
160				t.Fatalf("iter %d: expected exactly one series, got %+v", iter, res.Series)
161			}
162			wins := res.Series[0].Windows
163			// 期望分组：朴素 uint64 下标（区间宽度小于 2^63，下标不会接近 uint64 上界）。
164			type gw struct {
165				s, e int64
166				c    int
167			}
168			var want []gw
169			indexOf := func(s, e int64) int {
170				for i := range want {
171					if want[i].s == s && want[i].e == e {
172						return i
173					}
174				}
175				return -1
176			}
177			for ts := range inRange {
178				off := uint64(ts) - uint64(start)
179				k := off / uint64(step)
180				ws := int64(uint64(start) + k*uint64(step))
181				we := ws + step - 1
182				if we > end || we < ws {
183					we = end
184				}
185				if i := indexOf(ws, we); i >= 0 {
186					want[i].c++
187				} else {
188					want = append(want, gw{ws, we, 1})
189				}
190			}
191			// 期望按起点升序。
192			for i := 1; i < len(want); i++ {
193				for j := i; j > 0 && want[j].s < want[j-1].s; j-- {
194					want[j], want[j-1] = want[j-1], want[j]
195				}
196			}
197			if len(wins) != len(want) {
198				t.Fatalf("iter %d [%d,%d] step %d: got %d windows, want %d: %+v vs %+v",
199					iter, start, end, step, len(wins), len(want), wins, want)
200			}
201			for i := range want {
202				if wins[i].Start != want[i].s || wins[i].End != want[i].e || wins[i].Count != want[i].c {
203					t.Fatalf("iter %d window %d = [%d,%d] c=%d avg=%v, want [%d,%d] c=%d",
204						iter, i, wins[i].Start, wins[i].End, wins[i].Count, wins[i].Average,
205						want[i].s, want[i].e, want[i].c)
206				}
207				if i > 0 && wins[i].Start <= wins[i-1].End {
208					t.Fatalf("iter %d: windows overlap/out of order: %+v", iter, wins)
209				}
210			}
211		}
212	}
